import{_ as e,o as a,c as s}from"./chunks/framework.D1Ss-Xl7.js";const h=JSON.parse(`{"title":"ssl Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"ssl","tag":"ssl","title":"ssl Tag","prev":null,"next":null,"posts":[{"title":"使用letsencrypt为自己的网站加密","url":"/posts/2018-04-08-website-https/","date":"2018-04-08 20:51","tags":["site","ssl"],"html":"<p>好吧，这次博客的更新稍微有点迟到了。因为自己各种忙着考驾照什么的，不过新的一年又要有新的开始了。最近买了 VPS 也就开始折腾起来了，讲讲如何用 letsencrypt 来给自己的网站颁发不要钱的证书，而且最近还支持通配符的二级域名了，想怎么开子网站都行！！！</p>\\n<h2 id=\\"dehydrated\\" tabindex=\\"-1\\">dehydrated <a class=\\"header-anchor\\" href=\\"#dehydrated\\" aria-label=\\"Permalink to &quot;dehydrated&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>浏览器的证书签名的步骤实在是很麻烦，所以有位热心的学生做了一个自动化脚本，可以自动生成脚本并且可以和其他脚本一起使用。达到一键签名证书。</p>\\n<h2 id=\\"letsencrypt-cloudflare-hook\\" tabindex=\\"-1\\">letsencrypt-cloudflare-hook <a class=\\"header-anchor\\" href=\\"#letsencrypt-cloudflare-hook\\" aria-label=\\"Permalink to &quot;letsencrypt-cloudflare-hook&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我把自己的 DNS 服务托管到 cloudflare 上，还可以使用 cloudflare 提供免费的 CDN 服务。最重要的一点是 cloudflare 有 API 接口。利用这个接口就可以自动完成 DNS-01 challenge。简单的来说，就是通过添加一条 DNS 记录来证明自己对这个域名的所有权，才能给这个域名颁发证书。</p>\\n<h2 id=\\"安装过程\\" tabindex=\\"-1\\">安装过程 <a class=\\"header-anchor\\" href=\\"#安装过程\\" aria-label=\\"Permalink to &quot;安装过程&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>知道了这两个工具之后，我们就可以开始配置证书了。具体的流程都写在项目的<a href=\\"https://github.com/kappataumu/letsencrypt-cloudflare-hook/blob/master/README.md\\" target=\\"_blank\\" rel=\\"noreferrer\\">文档</a>里面了。我这里主要是讲述下遇到的坑，首先我自己的服务器环境是 CentOS7，使用的是默认的 python2 的环境。需要安装<code>cryptography</code>的库才能顺利完成编译。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">sudo</span><span style=\\"color:#032F62\\"> yum</span><span style=\\"color:#032F62\\"> install</span><span style=\\"color:#032F62\\"> gcc</span><span style=\\"color:#032F62\\"> libffi-devel</span><span style=\\"color:#032F62\\"> python-devel</span><span style=\\"color:#032F62\\"> openssl-devel</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>其次，配置环境最好保存在<code>dehydrated/config</code>里，这样就没必要每次都设置环境变量。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#005CC5\\">echo</span><span style=\\"color:#032F62\\"> \\"export CF_EMAIL=user@example.com\\"</span><span style=\\"color:#D73A49\\"> >></span><span style=\\"color:#032F62\\"> config</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">echo</span><span style=\\"color:#032F62\\"> \\"export CF_KEY=K9uX2HyUjeWg5AhAb\\"</span><span style=\\"color:#D73A49\\"> >></span><span style=\\"color:#032F62\\"> config</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">echo</span><span style=\\"color:#032F62\\"> \\"export CF_DEBUG=true\\"</span><span style=\\"color:#D73A49\\"> >></span><span style=\\"color:#032F62\\"> config</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>CF_KEY 就是 cloudflare 里面的 Global API Key，替换一下就好了。因为我们要配置的域名包含所有的二级域名，所以需要新建一个<code>dehydrated/domains.txt</code>文件，并写入：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>icehoney.me *.icehoney.me</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这样就会对主域名和所有二级域名生效。</p>\\n<p>之后再执行命令，<code>./dehydrated -c -t dns-01 -k 'hooks/cloudflare/hook.py'</code>。如果没有问题就可以看到成功生成的日志。</p>\\n<p>参考：</p>\\n<p><a href=\\"https://github.com/lukas2511/dehydrated\\" target=\\"_blank\\" rel=\\"noreferrer\\">dehydrated</a></p>\\n<p><a href=\\"https://github.com/kappataumu/letsencrypt-cloudflare-hook\\" target=\\"_blank\\" rel=\\"noreferrer\\">letsencrypt-cloudflare-hook</a></p>\\n<p><a href=\\"https://stackoverflow.com/questions/22073516/failed-to-install-python-cryptography-package-with-pip-and-setup-py\\" target=\\"_blank\\" rel=\\"noreferrer\\">Failed to install Python Cryptography package with PIP and setup.py\\nAsk Question</a></p>\\n"}]},"relativePath":"tags/ssl/index.md","filePath":"tags/[slug].md"}`),n={name:"tags/ssl/index.md"};function l(t,o,p,r,c,d){return a(),s("div")}const u=e(n,[["render",l]]);export{h as __pageData,u as default};
